    LANGUAGE_WRAPPER = 'Fix an odd prime {p}. For each positive integer n, let L_p(n) be the last non-zero digit of n! when written in base {p}. Let k_p(t) be the {t}-th smallest positive integer k such that L_p(k n) = L_p(n) for all integers n ≥ 1. For the given {p} and {t}, how many base-10 digits does k_p(t) have?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose an odd prime p (≥7 to keep instances non-trivial)
primes = [7, 11, 13, 17, 19, 23, 29, 31]
# Choose t so that k = p^(2*(t-1)) has enough digits to be non-trivial
# Retry until the decimal length of k is at least 10
while True:
    p = rng.choice(primes)
    t = rng.randint(6, 12)  # yields exponents between 10 and 22
    k = pow(p, 2*(t-1))
